import sys
from math import gcd

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    forbidden = set()
    if n > 0:
        for _ in range(n):
            forbidden.add(int(next(iterator)))

    if m == 1:
        print(0)
        print()
        return

    allowed = []
    for i in range(m):
        if i not in forbidden:
            allowed.append(i)

    if not allowed:
        print(0)
        print()
        return


    def get_sequence(start_val, current_prod):
        seq = []
        visited = {current_prod}
        curr = current_prod

        while True:
            if curr == 0:
                break

            found_next = False
            for x in range(m):
                if x in forbidden:
                    continue
                nxt = (curr * x) % m
                if nxt in forbidden:
                    continue
                if nxt in visited:
                    continue

                if nxt == 0:
                    seq.append(x)
                    visited.add(0)
                    curr = 0
                    found_next = True
                    break
                else:
                    if gcd(nxt, m) == gcd(curr, m):
                        seq.append(x)
                        visited.add(nxt)
                        curr = nxt
                        found_next = True
                        break

            if not found_next:
                if curr != 0:
                    if 0 not in visited and 0 not in forbidden:
                        for x in range(m):
                            if x in forbidden:
                                continue
                            if (curr * x) % m == 0:
                                seq.append(x)
                                visited.add(0)
                                curr = 0
                                break
                break

        return seq

    best_seq = []

    for start in allowed:
        if start == 0:
            continue

        if gcd(start, m) == 1:
            temp_seq = get_sequence(start, start)
            if len(temp_seq) > len(best_seq):
                best_seq = temp_seq
            break

    if not best_seq:
        for start in allowed:
            if start == 0:
                continue
            temp_seq = get_sequence(start, start)
            if len(best_seq) < len(temp_seq):
                best_seq = temp_seq
            elif len(best_seq) == len(temp_seq):
                if temp_seq:
                    break

    if not best_seq and 0 in allowed:
        best_seq = [0]

    print(len(best_seq))
    print(" ".join(map(str, best_seq)))

